import os
from typing import Any, Dict, List, Optional, Union

import boto3


def _load_document_bytes(document: Union[str, bytes, bytearray]) -> bytes:
    if isinstance(document, (bytes, bytearray)):
        return bytes(document)
    if isinstance(document, str):
        with open(document, "rb") as f:
            return f.read()
    raise TypeError("document must be a file path, bytes, or bytearray")


def _block_map(blocks: List[Dict[str, Any]]) -> Dict[str, Dict[str, Any]]:
    return {block["Id"]: block for block in blocks if "Id" in block}


def _child_ids(block: Dict[str, Any], relationship_type: str) -> List[str]:
    ids: List[str] = []
    for rel in block.get("Relationships", []):
        if rel.get("Type") == relationship_type:
            ids.extend(rel.get("Ids", []))
    return ids


def _extract_text_from_block(
    block: Dict[str, Any],
    blocks_by_id: Dict[str, Dict[str, Any]],
) -> str:
    words: List[str] = []
    for child_id in _child_ids(block, "CHILD"):
        child = blocks_by_id.get(child_id)
        if not child:
            continue
        if child.get("BlockType") == "WORD":
            text = child.get("Text", "")
            if text:
                words.append(text)
        elif child.get("BlockType") == "SELECTION_ELEMENT":
            if child.get("SelectionStatus") == "SELECTED":
                words.append("X")
    return " ".join(words).strip()


def _find_value_block(
    key_block: Dict[str, Any],
    blocks_by_id: Dict[str, Dict[str, Any]],
) -> Optional[Dict[str, Any]]:
    for value_id in _child_ids(key_block, "VALUE"):
        value_block = blocks_by_id.get(value_id)
        if value_block and value_block.get("BlockType") == "KEY_VALUE_SET" and "VALUE" in value_block.get("EntityTypes", []):
            return value_block
    return None


def _extract_confidence(*blocks: Optional[Dict[str, Any]]) -> Optional[float]:
    confidences = [b.get("Confidence") for b in blocks if b and isinstance(b.get("Confidence"), (int, float))]
    if not confidences:
        return None
    return min(float(c) for c in confidences)


def extract_key_value_pairs(
    document: Union[str, bytes, bytearray],
    region_name: Optional[str] = None,
) -> Dict[str, Dict[str, Any]]:
    client = boto3.client("textract", region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1")
    document_bytes = _load_document_bytes(document)

    response = client.analyze_document(
        Document={"Bytes": document_bytes},
        FeatureTypes=["FORMS"],
    )

    blocks = response.get("Blocks", [])
    blocks_by_id = _block_map(blocks)

    results: Dict[str, Dict[str, Any]] = {}

    for block in blocks:
        if block.get("BlockType") != "KEY_VALUE_SET":
            continue
        if "KEY" not in block.get("EntityTypes", []):
            continue

        key_text = _extract_text_from_block(block, blocks_by_id)
        if not key_text:
            continue

        value_block = _find_value_block(block, blocks_by_id)
        value_text = _extract_text_from_block(value_block, blocks_by_id) if value_block else ""

        entry = {
            "value": value_text,
            "key_confidence": float(block.get("Confidence", 0.0)),
            "value_confidence": float(value_block.get("Confidence", 0.0)) if value_block else None,
            "confidence": _extract_confidence(block, value_block),
        }

        if key_text in results:
            existing = results[key_text]
            existing_list = existing.get("duplicates")
            if existing_list is None:
                existing["duplicates"] = [entry]
            else:
                existing_list.append(entry)
        else:
            results[key_text] = entry

    return results
